SELECT o.*, g.title as goodsTitle, g.images as goodsImage, g.status as goodsStatus, eg.title as exchangeGoodsTitle, eg.images as exchangeGoodsImage, eg.status as exchangeGoodsStatus, b.nickname as buyerName, s.nickname as sellerName FROM goods_order o LEFT JOIN goods_info g ON o.goods_id = g.goods_id LEFT JOIN goods_info eg ON o.exchange_goods_id = eg.goods_id LEFT JOIN sys_user b ON o.buyer_id = b.user_id LEFT JOIN sys_user s ON o.seller_id = s.user_id
o.buyer_id = #{userId}
o.seller_id = #{userId}
ORDER BY o.create_time DESC

SELECT o.*, g.title as goodsTitle, g.images as goodsImage, g.status as goodsStatus, eg.title as exchangeGoodsTitle, eg.images as exchangeGoodsImage, eg.status as exchangeGoodsStatus, b.nickname as buyerName, s.nickname as sellerName FROM goods_order o LEFT JOIN goods_info g ON o.goods_id = g.goods_id LEFT JOIN goods_info eg ON o.exchange_goods_id = eg.goods_id LEFT JOIN sys_user b ON o.buyer_id = b.user_id LEFT JOIN sys_user s ON o.seller_id = s.user_id
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR g.title LIKE CONCAT('%', #{keyword}, '%') OR eg.title LIKE CONCAT('%', #{keyword}, '%') OR b.nickname LIKE CONCAT('%', #{keyword}, '%') OR s.nickname LIKE CONCAT('%', #{keyword}, '%') OR b.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_no LIKE CONCAT('%', #{keyword}, '%') )
AND o.trade_type = #{tradeType}
AND o.status = #{status}
ORDER BY o.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM goods_order o LEFT JOIN goods_info g ON o.goods_id = g.goods_id LEFT JOIN goods_info eg ON o.exchange_goods_id = eg.goods_id LEFT JOIN sys_user b ON o.buyer_id = b.user_id LEFT JOIN sys_user s ON o.seller_id = s.user_id
AND ( o.order_no LIKE CONCAT('%', #{keyword}, '%') OR g.title LIKE CONCAT('%', #{keyword}, '%') OR eg.title LIKE CONCAT('%', #{keyword}, '%') OR b.nickname LIKE CONCAT('%', #{keyword}, '%') OR s.nickname LIKE CONCAT('%', #{keyword}, '%') OR b.student_no LIKE CONCAT('%', #{keyword}, '%') OR s.student_no LIKE CONCAT('%', #{keyword}, '%') )
AND o.trade_type = #{tradeType}
AND o.status = #{status}
